# Break My Fix finding 2, generated by Tracefix: Listener.port returns a wrong value.
# Property (docstring): None returns self.default_port for any default
# Quote: An unset (None) or blank value gives `self.default_port`.
# Run it with pytest: it fails for as long as the code breaks this property.

import copy

from gateway.listener import Listener


def test_break_my_fix_2() -> None:
    self_after = Listener(default_port=9000)
    self = copy.deepcopy(self_after)
    raw = None
    # The property applies to this input: raw is None
    result = self_after.port(raw=raw)
    assert result == (self.default_port)
